from pathlib import Path


def replace(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f"missing in {path}: {old!r}")
    p.write_text(text.replace(old, new, 1))


