Path('internal/query/metatags_test.go').write_text('''package query\n\nimport (\n\t"strings"\n\t"testing"\n)\n\nfunc TestMetaTagCatalogAndParser(t *testing.T) {\n\tdefinitions := MetaTags()\n\tif len(definitions) != 2 {\n\t\tt.Fatalf("got %d metatags, want 2", len(definitions))\n\t}\n\tif definitions[0].Name != MetaTagTagged || definitions[1].Name != MetaTagFilenameContains {\n\t\tt.Fatalf("unexpected catalog: %+v", definitions)\n\t}\n\tparsed, err := ParseMetaTag(`@filename_contains:Summer 100%_Set`)\n\tif err != nil {\n\t\tt.Fatalf("parse filename metatag: %v", err)\n\t}\n\tif parsed.Value != `Summer 100%_Set` || !parsed.Definition.RequiresValue {\n\t\tt.Fatalf("unexpected parsed metatag: %+v", parsed)\n\t}\n\tif _, err := ParseMetaTag(`@filename_contains:`); err == nil {\n\t\tt.Fatal("expected empty filename_contains value to fail")\n\t}\n}\n\nfunc TestFilenameContainsBuildLocationsTargetsBasenameCaseInsensitivelyAndEscapesWildcards(t *testing.T) {\n\texpr, err := Parse(`@filename_contains:"100%_SET"`)\n\tif err != nil {\n\t\tt.Fatal(err)\n\t}\n\tif err := ValidateAST(expr); err != nil {\n\t\tt.Fatal(err)\n\t}\n\tqueryText, args := BuildLocations(expr, nil)\n\tif len(args) != 1 || args[0] != `%100\\%\\_SET%` {\n\t\tt.Fatalf("unexpected LIKE args: %#v", args)\n\t}\n\tfor _, fragment := range []string{"WITH RECURSIVE path_parts", "replace(path, char(92), '/')", "p.rest = ''", "lower(p.part) LIKE lower(?) ESCAPE '\\\\'"} {\n\t\tif !strings.Contains(queryText, fragment) {\n\t\t\tt.Fatalf("query missing %q: %s", fragment, queryText)\n\t\t}\n\t}\n}\n''')
Path('internal/serve/search_saved_metatags_test.go').write_text('''package serve\n\nimport "testing"\n\nfunc TestMetaTagDTOsExposeCompleteQueryCatalog(t *testing.T) {\n\titems := metaTagDTOs()\n\tif len(items) != 2 {\n\t\tt.Fatalf("got %d metatags, want 2", len(items))\n\t}\n\tif items[0].Syntax != "@tagged" || items[0].RequiresValue {\n\t\tt.Fatalf("unexpected tagged metadata: %+v", items[0])\n\t}\n\tif items[1].Syntax != "@filename_contains:" || !items[1].RequiresValue {\n\t\tt.Fatalf("unexpected filename metadata: %+v", items[1])\n\t}\n}\n''')
Path('frontend/src/lib/search/specialSuggestions.test.ts').write_text('''import { describe, expect, it } from 'vitest';\nimport { specialSearchSuggestions } from './specialSuggestions';\n\nconst metaTags = [\n  { syntax: '@tagged', hint: 'has tags', requires_value: false },\n  { syntax: '@filename_contains:', hint: 'filename contains', requires_value: true }\n];\n\ndescribe('specialSearchSuggestions', () => {\n  it('uses the backend catalog for metatags and hides them on unrelated input', () => {\n    expect(specialSearchSuggestions('@t', [], metaTags)).toEqual([\n      { commit: '@tagged', ns: '', val: '@tagged', hint: 'has tags' }\n    ]);\n    expect(specialSearchSuggestions('@f', [], metaTags)).toEqual([\n      { commit: '@filename_contains:', ns: '@filename_contains', val: '', hint: 'filename contains', partial: true }\n    ]);\n    expect(specialSearchSuggestions('artist', [], metaTags)).toEqual([]);\n  });\n\n  it('does not invent metatags when the backend catalog is empty', () => {\n    expect(specialSearchSuggestions('@t')).toEqual([]);\n    expect(specialSearchSuggestions('@f')).toEqual([]);\n  });\n\n  it('completes supported media kinds after type:', () => {\n    expect(specialSearchSuggestions('type:v', [], metaTags)).toEqual([\n      { commit: 'type:video', ns: 'type', val: 'video', hint: 'media type' }\n    ]);\n    expect(specialSearchSuggestions('type:', [], metaTags)).toHaveLength(5);\n  });\n\n  it('supports negation and excludes already committed exact expressions', () => {\n    expect(specialSearchSuggestions('-@t', [], metaTags)).toEqual([\n      { commit: '-@tagged', ns: '', val: '@tagged', hint: 'has tags' }\n    ]);\n    expect(specialSearchSuggestions('@t', ['@tagged'], metaTags)).toEqual([]);\n    expect(specialSearchSuggestions('type:v', ['type:video'], metaTags)).toEqual([]);\n  });\n});\n''')
